// For the #WCCChallenge, theme: "zoo".
// Here are the 120 unicode emojis in the "animal and nature" category!
// There are 15 birds, 12 bugs, 53 mammals, 9 marine animals, 8 reptiles, 10 flowers, 12 plants, and 1 amphibian.
// Data on emoji meanings and usage frequency from the Unicode Foundation:
// https://home.unicode.org/emoji/emoji-frequency/

let emojis = [];
let categories = [];
let catsizes = [];
let positions = [];
let selected;
let pick = null;
let zoom;
let rank = 'category';
let sort = 'Random';
let sorts = ['Random', 'Category', 'Rank'];
let sortindex = 0;
let zoo;

function preload() {
	table1 = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/zooanimals3.csv', 'header');
	table2 = loadTable('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/zooanimals2.csv', 'header');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	zoo = createGraphics(width, height);
	zoom = 1;
	textAlign(CENTER, CENTER);
	makePositions();
	makeEmojis();
	button = createButton('Category Rank');
	button.style('font-size', '18px');
	button.position(10, 10);
	button.mousePressed(changeRank);
	button.style('width','150px');
	button2 = createButton('Category Sort');
	button2.style('font-size', '18px');
	button2.position(10, height - 40);
	button2.mousePressed(changeSort);
	button2.style('width','150px');
	announce = createP('Test');
	announce.position(10, 30)
	announce.style('font-size', '18px');
	announce.style('font-family', 'Arial')
}

function draw() {
	background(255);
	image(zoo, 0, 0)
	translate(width / 2, height / 2);
	scale(zoom);
	for (let e of emojis) {
		if (e == selected) continue;
		e.show();
	}
	if (selected) {
		selected.show();
		let txt = 'name: ' + selected.name + '</br>'
		txt += 'category: ' + selected.cat + '</br>'
		txt += 'subcategory: ' + selected.subcat + '</br>'
		if (rank == 'category') txt += 'category rank: ' + selected.catrank + '</br>'
		else if (rank == 'overall') txt += 'overall rank: ' + selected.rank + '</br>'
		announce.html(txt)
	} else {
		var txt = 'name: ' + '</br>'
		txt += 'category: ' + '</br>'
		txt += 'subcategory: ' + '</br>'
		if (rank == 'category') txt += 'category rank: ' + '</br>'
		else if (rank == 'overall') txt += 'overall rank: ' + '</br>'
		announce.html(txt)
	}
	drawCage();
}

function mouseMoved() {
	selected = null;
	for (let e of emojis) {
		if (e.contains(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2) / zoom, ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2) / zoom)) {
			selected = e;
			break;
		}
	}
}

function makeEmojis() {
	if (sort == 'Random') table = table1;
	else if (sort == 'Category') table = table1;
	else table = table2;
	emojis = [];
	let ang = -HALF_PI;
	zoo.clear();
	makePositions();
	for (let i = 0; i < table.getRowCount(); i++) {
		var rank = table.getString(i, 1);
		let sym = table.getString(i, 2);
		let cat = table.getString(i, 4);
		let subcat = table.getString(i, 5);
		let name = table.getString(i, 6);
		let catrank = table.getString(i, 7);
		let grank = table.getString(i, 8);
		let catsize = catsizes[categories.indexOf(subcat)];
		let pos;
		if (sort == 'Random') pos = random(positions);
		else pos = positions[i];
		emojis.push(new Emoji(rank, sym, cat, subcat, name, catrank, grank, catsize, pos, ang));
		if (sort == 'Random') positions.splice(positions.indexOf(pos), 1);
	}

	for (let e of emojis) {
		zoo.push();
		zoo.translate(width / 2, height / 2);
		zoo.translate(e.pos);
		zoo.textSize(height / 30);
		zoo.textAlign(CENTER, CENTER)
		zoo.text(e.symbol, 0, 0);
		zoo.pop();
	}
	zoo.push();
	zoo.translate(width / 2, height / 2);
	zoo.textAlign(CENTER, CENTER);
	zoo.textSize(height / 20);
	zoo.text("☮️", 0, height / 150);
	zoo.pop();
	frameCount = 0;
}

function changeRank() {
	if (rank == 'category') {
		rank = 'overall';
		button.html('Overall Rank');
	} else {
		rank = 'category';
		button.html('Category Rank');
	}
}

function changeSort() {
	sortindex = (sortindex + 1) % 3;
	button2.html(sorts[(sortindex+1)%3] + ' Sort');
	sort = sorts[sortindex];
	makePositions();
	makeEmojis();
}

function makePositions() {
	positions = [];
	let num = 11;
	for (let row = 0; row < num; row++) {
		for (let col = 0; col < num; col++) {
			let x = map(col, 0, num - 1, -height / 3, height / 3);
			let y = map(row, 0, num - 1, -height / 3, height / 3);
			if (x == 0 && y == 0) continue;
			var pos = createVector(x, y);
			positions.push(pos);
		}
	}
}

function drawCage() {
	push();
	rectMode(CENTER);
	noFill();
	stroke(100, 50);
	strokeWeight(height / 300);
	strokeCap(SQUARE);
	for (let i = 0; i < 12; i++) {
		var x = map(i, 0, 11, -height / 2.7, height / 2.7);
		line(x, -height / 2.7, x, height / 2.7);
		line(-height / 2.7, x, height / 2.7, x)
	}
	pop();
}

